mapper.select:
SELECT * FROM ( SELECT R.REVIEW_NO, R.COMPANION_NO, R.MEMBER_NO, R.TITLE, R.CONTENT, R.RATING, R.IMAGE_URL, R.CONTENT_IMAGES, R.STATUS, TO_CHAR(R.CREATED_AT, 'YYYY-MM-DD') AS CREATED_AT, M.NICKNAME AS AUTHOR_NICKNAME, M.PROFILE_IMAGE AS AUTHOR_PROFILE, CB.TITLE AS COMPANION_TITLE, ROW_NUMBER() OVER (ORDER BY
R.RATING DESC, R.CREATED_AT DESC R.RATING ASC, R.CREATED_AT DESC R.CREATED_AT DESC
) AS RN FROM COMPANION_REVIEW R JOIN MEMBER M ON R.MEMBER_NO = M.MEMBER_NO LEFT JOIN COMPANION_BOARD CB ON R.COMPANION_NO = CB.COMPANION_NO WHERE R.STATUS = 'Y'
AND (UPPER(R.TITLE) LIKE '%' || UPPER(#{search}) || '%' OR UPPER(R.CONTENT) LIKE '%' || UPPER(#{search}) || '%')
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.insert:
INSERT INTO COMPANION_REVIEW (
    REVIEW_NO, COMPANION_NO, MEMBER_NO,
    TITLE, CONTENT, RATING, IMAGE_URL, CONTENT_IMAGES
) VALUES (
    SEQ_REVIEW_NO.NEXTVAL, #{companionNo}, #{memberNo},
    #{title}, #{content}, #{rating}, #{imageUrl}, #{contentImages}
)

mapper.update:
UPDATE COMPANION_REVIEW
SET STATUS = 'N', UPDATED_AT = SYSDATE
WHERE REVIEW_NO = #{reviewNo}
  AND MEMBER_NO = #{memberNo}
